// spec: specs/chat-conversations.md
// seed: tests/seed.chat.spec.ts
// Безопасность прода: до набора текста все не-GET/HEAD/OPTIONS запросы блокируются.
// Не нажимать кнопку отправки и Ctrl/Cmd+Enter. Поле очищается в finally.
import { test, expect, Page } from '@playwright/test';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

const CONVERSATION_URL =
  '/messages?conversation=a5002a64-d87f-4434-9974-731aaf9fd5c0&business=c676c730-194b-4bb7-a21b-f84ecbde34c2';
const LINE1 = 'QA-AUTO-שורה1';
const LINE2 = 'QA-AUTO-שורה2';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

async function enterAddsNewline(page: Page) {
  // 1. Открыть существующую переписку
  await page.goto(CONVERSATION_URL);
  const input = page.getByPlaceholder('כתוב הודעה...');
  await expect(input).toBeVisible();

  // 2. Блок записи — до набора текста
  const blocked: string[] = [];
  await page.route('**/*', (route) => {
    const req = route.request();
    if (SAFE_METHODS.includes(req.method())) return route.fallback();
    blocked.push(`${req.method()} ${req.url()}`);
    return route.abort('blockedbyclient');
  });

  try {
    // 3–5. Текст, Enter, текст
    await input.click();
    await input.pressSequentially(LINE1);
    await input.press('Enter');
    await input.pressSequentially(LINE2);

    // Enter добавил перенос строки, поле не очищено
    await expect(input).toHaveValue(`${LINE1}\n${LINE2}`);
    // Сообщение в переписке не появилось (пузыри — <p>; сама textarea getByText находит, поэтому её не считаем)
    await expect(page.locator('p').filter({ hasText: LINE1 })).toHaveCount(0);
    // Попытки создать сообщение не было
    const messageWrites = blocked.filter((r) => /\/rest\/v1\/[^?]*message/i.test(r));
    expect(messageWrites, `Заблокированы запросы записи сообщения:\n${blocked.join('\n')}`).toEqual([]);
    if (blocked.length) test.info().annotations.push({ type: 'blocked-requests', description: blocked.join('\n') });
  } finally {
    // 6. Очистка поля
    await input.fill('');
    await expect(input).toHaveValue('');
  }
}

test.describe('Чат / переписки — поле «כתוב הודעה...»', () => {
  test('Android: Enter в поле «כתוב הודעה...» добавляет перенос строки и не отправляет #1da60a @android @prod-safe', async ({ page }) => {
    await enterAddsNewline(page);
  });

  test('Десктоп: Enter в поле «כתוב הודעה...» добавляет перенос строки и не отправляет #1da60a @desktop @prod-safe', async ({ page }) => {
    await enterAddsNewline(page);
  });
});
